  1	/**
  2	 * GUI API Route Handlers — Model Registry Domain
  3	 *
  4	 * All REST handlers for the /api/models, /api/model-assignments, and
  5	 * /api/personas endpoints. Follows the domain-split pattern established by
  6	 * `api-repos.ts` — each API domain gets its own handler file imported from
  7	 * `server.ts`.
  8	 *
  9	 * Routes provided:
 10	 *   GET    /api/models                       — list models (auto-init local.json from defaults)
 11	 *   PUT    /api/models                       — bulk-save model list (auto-assign UUIDs)
 12	 *   POST   /api/models/load-defaults         — merge default.json into local.json
 13	 *   GET    /api/model-assignments            — get assignments enriched with stale flag
 14	 *   PUT    /api/model-assignments            — validate + persist assignment data
 15	 *   POST   /api/model-assignments/replace    — swap all occurrences of one model UUID
 16	 *   GET    /api/personas                     — list personas from name-mapping.json
 17	 *   POST   /api/personas/rebuild             — spawn node scripts/build-personas.js
 18	 *
 19	 * Validation rules:
 20	 *   - `PUT /api/models`: auto-assigns UUIDv4 to entries missing `id`; rejects
 21	 *     duplicate slugs and the reserved slug `"inherit"` on non-sentinel entries.
 22	 *   - `PUT /api/models`: returns 409 Conflict when a deletion would leave a
 23	 *     referenced model with no replacement (user must use Replace Model first).
 24	 *   - `PUT /api/model-assignments`: validates all model UUIDs exist in registry
 25	 *     and all persona keys exist in name-mapping.json.
 26	 *   - `POST /api/model-assignments/replace`: rejects same-model swap and
 27	 *     rejects when old_model_id is not currently referenced.
 28	 *
 29	 * Error shape: { error: { code: string, message: string } }
 30	 *   NOT_FOUND        → 404
 31	 *   VALIDATION_ERROR → 400
 32	 *   CONFLICT         → 409
 33	 *   (unhandled)      → 500
 34	 *
 35	 * STDIO discipline: this file never writes to process.stdout.
 36	 */
 37	
 38	import { readFile, stat } from 'fs/promises';
 39	import { join } from 'path';
 40	import { spawn } from 'child_process';
 41	import { randomUUID } from 'crypto';
 42	import { z } from 'zod';
 43	import { ApiError } from '../src/gui/errors.js';
 44	import { WORKSPACE_ROOT } from '../src/utils/ledger-root.js';
 45	import {
 46	  readModels,
 47	  writeModels,
 48	  readAssignments,
 49	  writeAssignments,
 50	  loadDefaults,
 51	  ModelRegistrySchema,
 52	  ModelAssignmentsSchema,
 53	  type ModelEntry,
 54	  type ModelAssignments,
 55	} from '../src/gui/model-registry.js';
 56	
 57	// Re-export ApiError so consumers can catch typed errors without importing
 58	// from a separate path.
 59	export { ApiError };
 60	
 61	// ---------------------------------------------------------------------------
 62	// Private helpers
 63	// ---------------------------------------------------------------------------
 64	
 65	function validationError(message: string, details?: unknown): never {
 66	  throw new ApiError('VALIDATION_ERROR', message, details);
 67	}
 68	
 69	function conflictError(message: string, details?: unknown): never {
 70	  throw new ApiError('CONFLICT', message, details);
 71	}
 72	
 73	/**
 74	 * Returns the absolute path to the model registry directory.
 75	 * `{WORKSPACE_ROOT}/personas/model-registry`
 76	 */
 77	function modelRegistryDir(): string {
 78	  return join(WORKSPACE_ROOT, 'personas', 'model-registry');
 79	}
 80	
 81	/**
 82	 * Returns the absolute path to name-mapping.json.
 83	 * `{WORKSPACE_ROOT}/personas/name-mapping.json`
 84	 */
 85	function nameMappingPath(): string {
 86	  return join(WORKSPACE_ROOT, 'personas', 'name-mapping.json');
 87	}
 88	
 89	/**
 90	 * Returns the mtime of a file, or `null` if the file does not exist.
 91	 */
 92	async function getMtime(filePath: string): Promise<Date | null> {
 93	  try {
 94	    const s = await stat(filePath);
 95	    return s.mtime;
 96	  } catch {
 97	    return null;
 98	  }
 99	}
100

201	 * new default entries and existing local entries are reported as conflicts but
202	 * do not block the merge.
203	 *
204	 * Returns the post-merge model list and the list of slug-collision conflicts.
205	 */
206	export async function handleLoadDefaults(): Promise<{
207	  models: ModelEntry[];
208	  conflicts: Array<{
209	    defaultEntry: ModelEntry;
210	    localEntry: ModelEntry;
211	    reason: 'slug_collision';
212	  }>;
213	}> {
214	  return loadDefaults();
215	}
216	
217	// ---------------------------------------------------------------------------
218	// GET /api/model-assignments
219	// ---------------------------------------------------------------------------
220	
221	/**
222	 * Staleness check.
223	 *
224	 * Returns `true` when `max(mtime(assignments.json), mtime(local.json))` is
225	 * **greater than** `mtime(name-mapping.json)`, indicating that the user
226	 * registry or assignments have changed since the last persona build.
227	 *
228	 * Staleness rules:
229	 * - Returns `false` when neither assignments.json nor local.json exist (no
230	 *   user modifications have been made yet — no build needed).
231	 * - Returns `false` when only `default.json` exists (mtime reflects Git
232	 *   checkout time, not user modification; excluded by design).
233	 * - Returns `false` when name-mapping.json does not exist (no build output to
234	 *   compare against).
235	 *
236	 * @internal
237	 */
238	async function computeStale(): Promise<boolean> {
239	  const registryDir = modelRegistryDir();
240	
241	  const [assignmentsMtime, localMtime, nameMappingMtime] = await Promise.all([
242	    getMtime(join(registryDir, 'assignments.json')),
243	    getMtime(join(registryDir, 'local.json')),
244	    getMtime(nameMappingPath()),
245	  ]);
246	
247	  // No user files exist → never stale
248	  if (assignmentsMtime === null && localMtime === null) {
249	    return false;
250	  }
251	
252	  // name-mapping.json doesn't exist → can't compare, not stale
253	  if (nameMappingMtime === null) {
254	    return false;
255	  }
256	
257	  // max(mtime(assignments.json), mtime(local.json))
258	  const userMtimes = [assignmentsMtime, localMtime].filter((m): m is Date => m !== null);
259	  const maxUserMtime = new Date(Math.max(...userMtimes.map((m) => m.getTime())));
260	
261	  return maxUserMtime > nameMappingMtime;
262	}
263	
264	/**
265	 * Returns the current model assignments enriched with a `stale` boolean.
266	 *
267	 * The `stale` flag indicates whether the persona build output (`name-mapping.json`)
268	 * is out of date relative to user-modified files. It is computed by
269	 * `computeStale()` and follows these rules:
270	 *
271	 * - `stale: true`  — `max(mtime(assignments.json), mtime(local.json))` is
272	 *   strictly greater than `mtime(name-mapping.json)`. The user has made
273	 *   registry or assignment changes since the last build; a rebuild is needed.
274	 * - `stale: false` — neither `assignments.json` nor `local.json` exist. No
275	 *   user modifications have been made yet; no build is needed.
276	 * - `stale: false` — `name-mapping.json` does not exist. There is no build
277	 *   output to compare against.
278	 * - `stale: false` — only `default.json` is newer than `name-mapping.json`.
279	 *   `default.json` mtime reflects Git checkout time, not a user modification,
280	 *   so it is excluded from the staleness comparison by design.
281	 *
282	 * Frontend consumers should show a "Rebuild personas" prompt when `stale: true`.
283	 */
284	export async function handleGetAssignments(): Promise<
285	  ModelAssignments & { stale: boolean }
286	> {
287	  const [assignments, stale] = await Promise.all([
288	    readAssignments(),
289	    computeStale(),
290	  ]);
291	  return { ...assignments, stale };
292	}
293	
294	// ---------------------------------------------------------------------------
295	// PUT /api/model-assignments
296	// ---------------------------------------------------------------------------
297	
298	/**
299	 * Request body schema for PUT /api/model-assignments.
300	 */
301	const UpdateAssignmentsBodySchema = ModelAssignmentsSchema;
302	
303	/**
304	 * Validates and persists model assignments.
305	 *
306	 * Validation:
307	 * - All model UUIDs referenced in the body must exist in the model registry.
308	 * - All persona keys in `persona_models` must appear as `id` values in
309	 *   `name-mapping.json`. Returns 400 when `name-mapping.json` doesn't exist.
310	 *
311	 * @param body - Raw parsed JSON request body.
312	 */
313	export async function handleUpdateAssignments(
314	  body: unknown
315	): Promise<ModelAssignments> {
316	  const parsed = UpdateAssignmentsBodySchema.safeParse(body);
317	  if (!parsed.success) {
318	    validationError(
319	      `Invalid assignments data: ${parsed.error.issues.map((i) => i.message).join('; ')}`
320	    );
321	  }
322	
323	  const data = parsed.data;
324	
325	  // 1. Validate name-mapping.json exists and load valid persona IDs
326	  let nameMappingRaw: string;
327	  try {
328	    nameMappingRaw = await readFile(nameMappingPath(), 'utf-8');
329	  } catch {
330	    validationError(
331	      'name-mapping.json does not exist. Run a persona build first before updating assignments.'
332	    );
333	  }
334	
335	  let nameMapping: unknown;
336	  try {
337	    nameMapping = JSON.parse(nameMappingRaw!);
338	  } catch {
339	    validationError('name-mapping.json is not valid JSON.');
340	  }
341	
342	  if (!Array.isArray(nameMapping)) {
343	    validationError('name-mapping.json must be a JSON array.');
344	  }
345	
346	  const validPersonaIds = new Set<string>(
347	    (nameMapping as Array<{ id?: unknown }>)
348	      .filter((e) => typeof e.id === 'string')
349	      .map((e) => e.id as string)
350	  );

351	
352	  // 2. Validate all persona keys in persona_models are valid persona IDs
353	  for (const personaKey of Object.keys(data.persona_models)) {
354	    if (!validPersonaIds.has(personaKey)) {
355	      validationError(
356	        `One or more persona keys in persona_models are not valid. ` +
357	          `Found ${validPersonaIds.size} valid persona ${validPersonaIds.size === 1 ? 'ID' : 'IDs'} in name-mapping.json.`
358	      );
359	    }
360	  }
361	
362	  // 3. Validate all model UUIDs exist in the registry
363	  const models = await readModels();
364	  const validModelIds = new Set(models.map((m) => m.id));
365	
366	  if (data.default_model_uuid !== undefined && !validModelIds.has(data.default_model_uuid)) {
367	    validationError(
368	      `default_model_uuid "${data.default_model_uuid}" does not exist in the model registry.`
369	    );
370	  }
371	
372	  for (const [personaKey, uuid] of Object.entries(data.persona_models)) {
373	    if (!validModelIds.has(uuid)) {
374	      validationError(
375	        `Model UUID "${uuid}" assigned to persona "${personaKey}" does not exist in the model registry.`
376	      );
377	    }
378	  }
379	
380	  // 4. Persist
381	  await writeAssignments(data);
382	  return data;
383	}
384	
385	// ---------------------------------------------------------------------------
386	// POST /api/model-assignments/replace
387	// ---------------------------------------------------------------------------
388	
389	/**
390	 * Request body schema for POST /api/model-assignments/replace.
391	 */
392	const ReplaceModelBodySchema = z
393	  .object({
394	    old_model_id: z.string().uuid(),
395	    new_model_id: z.string().uuid(),
396	  })
397	  .strict();
398	
399	/**
400	 * Swaps all occurrences of `old_model_id` with `new_model_id` in the current
401	 * assignments.
402	 *
403	 * Rejects with 400 when:
404	 * - `old_model_id === new_model_id`
405	 * - `old_model_id` is not currently referenced in any assignment
406	 *
407	 * Both UUIDs must exist in the model registry.
408	 *
409	 * @param body - Raw parsed JSON request body.
410	 */
411	export async function handleReplaceAssignedModel(
412	  body: unknown
413	): Promise<ModelAssignments> {
414	  const parsed = ReplaceModelBodySchema.safeParse(body);
415	  if (!parsed.success) {
416	    validationError(
417	      `Invalid replace body: ${parsed.error.issues.map((i) => i.message).join('; ')}`
418	    );
419	  }
420	
421	  const { old_model_id, new_model_id } = parsed.data;
422	
423	  // Reject same-model replacement
424	  if (old_model_id === new_model_id) {
425	    validationError('Source and target models must be different.');
426	  }
427	
428	  // Validate both UUIDs exist in the registry
429	  const models = await readModels();
430	  const validModelIds = new Set(models.map((m) => m.id));
431	
432	  if (!validModelIds.has(old_model_id)) {
433	    validationError(
434	      `old_model_id "${old_model_id}" does not exist in the model registry.`
435	    );
436	  }
437	
438	  if (!validModelIds.has(new_model_id)) {
439	    validationError(
440	      `new_model_id "${new_model_id}" does not exist in the model registry.`
441	    );
442	  }
443	
444	  // Load current assignments
445	  const assignments = await readAssignments();
446	
447	  // Check that old_model_id is actually referenced
448	  let referenced = false;
449	  if (assignments.default_model_uuid === old_model_id) {
450	    referenced = true;
451	  }
452	  for (const uuid of Object.values(assignments.persona_models)) {
453	    if (uuid === old_model_id) {
454	      referenced = true;
455	      break;
456	    }
457	  }
458	
459	  if (!referenced) {
460	    validationError(
461	      `Model "${old_model_id}" is not referenced in any current assignment. Nothing to replace.`
462	    );
463	  }
464	
465	  // Perform the swap
466	  const updated: ModelAssignments = {
467	    default_model_uuid:
468	      assignments.default_model_uuid === old_model_id
469	        ? new_model_id
470	        : assignments.default_model_uuid,
471	    persona_models: Object.fromEntries(
472	      Object.entries(assignments.persona_models).map(([k, v]) => [
473	        k,
474	        v === old_model_id ? new_model_id : v,
475	      ])
476	    ),
477	  };
478	
479	  await writeAssignments(updated);
480	  return updated;
481	}
482	
483	// ---------------------------------------------------------------------------
484	// GET /api/personas
485	// ---------------------------------------------------------------------------
486	
487	/**
488	 * Minimal persona shape exposed by `GET /api/personas`.
489	 *
490	 * The required fields (`id`, `role`, `suite`) are always present. The optional
491	 * fields are only populated after WP-003 is implemented and a persona build has
492	 * run — before that, `name-mapping.json` may only carry the required fields.
493	 *
494	 * @field id        - Unique persona identifier used as the key in model
495	 *                    assignments (`persona_models` map). Use this value when
496	 *                    calling `PUT /api/model-assignments`.
497	 * @field role      - Human-readable display name for the persona.
498	 * @field suite     - The persona suite this persona belongs to (e.g. `"ledger"`,
499	 *                    `"standalone"`).
500	 * @field model     - Optional resolved model name (e.g. `"claude-opus-4-5"`).

501	 *                    Present only after a build; may be undefined before first build.
